import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"run","description":"","frontmatter":{},"headers":[],"relativePath":"fr/cli/run.md","filePath":"fr/cli/run.md","lastUpdated":1784903584000}'),s={name:"fr/cli/run.md"};function n(o,e,d,l,c,u){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="run" tabindex="-1">run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;run&quot;">​</a></h1><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><p>Lancer l&#39;explorateur d&#39;API <strong>TUI (Interface Utilisateur Terminal)</strong> interactif. C&#39;est une application plein écran pour rechercher, parcourir, inspecter et invoquer des points d&#39;accès API sans quitter le terminal.</p><h2 id="quand-l-utiliser" tabindex="-1">Quand l&#39;utiliser <a class="header-anchor" href="#quand-l-utiliser" aria-label="Permalink to &quot;Quand l&#39;utiliser&quot;">​</a></h2><ul><li>Vous voulez explorer vos API de manière interactive</li><li>Vous devez rechercher un point d&#39;accès spécifique dans toutes les specs</li><li>Vous voulez parcourir la hiérarchie spec → collection → tag → point d&#39;accès</li><li>Vous voulez tester un appel API avant de configurer le serveur MCP</li></ul><h2 id="syntaxe" tabindex="-1">Syntaxe <a class="header-anchor" href="#syntaxe" aria-label="Permalink to &quot;Syntaxe&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [chemin]</span></span></code></pre></div><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Position</th><th>Requis</th><th>Description</th></tr></thead><tbody><tr><td><code>chemin</code></td><td>1</td><td>Non</td><td>Répertoire de l&#39;espace de travail. S&#39;il est omis, résolution via les règles de résolution de chemin.</td></tr></tbody></table><h2 id="drapeaux" tabindex="-1">Drapeaux <a class="header-anchor" href="#drapeaux" aria-label="Permalink to &quot;Drapeaux&quot;">​</a></h2><p>Aucun.</p><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><h3 id="mode-recherche" tabindex="-1">Mode Recherche <a class="header-anchor" href="#mode-recherche" aria-label="Permalink to &quot;Mode Recherche&quot;">​</a></h3><p>Recherche en texte intégral dans tous les points d&#39;accès de toutes les specs. Prend en charge le filtrage par méthode HTTP, étiquette et chemin.</p><ul><li>Saisissez une requête pour rechercher les noms, chemins et descriptions des points d&#39;accès</li><li>Filtrez les résultats par méthode (GET, POST, PUT, DELETE, etc.)</li><li>Affichez les détails d&#39;un point d&#39;accès avec une seule touche</li></ul><h3 id="mode-parcourir" tabindex="-1">Mode Parcourir <a class="header-anchor" href="#mode-parcourir" aria-label="Permalink to &quot;Mode Parcourir&quot;">​</a></h3><p>Navigation arborescente dans la hiérarchie des specs :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec → Collection → Tag → Point d&#39;accès</span></span></code></pre></div><ul><li>Descendez dans l&#39;arborescence pour trouver des points d&#39;accès spécifiques</li><li>Affichez les détails d&#39;un point d&#39;accès (paramètres, corps de requête, réponses)</li><li>Invoquez l&#39;API directement depuis la TUI</li></ul><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Touche</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Naviguer vers le haut/bas</td></tr><tr><td><code>Entrée</code></td><td>Sélectionner ou ouvrir</td></tr><tr><td><code>Échap</code></td><td>Revenir en arrière</td></tr><tr><td><code>Tab</code></td><td>Basculer entre les modes Recherche et Parcourir</td></tr><tr><td><code>/</code></td><td>Activer la saisie de recherche</td></tr><tr><td><code>q</code></td><td>Quitter</td></tr></tbody></table><h2 id="verification-post-commande" tabindex="-1">Vérification post-commande <a class="header-anchor" href="#verification-post-commande" aria-label="Permalink to &quot;Vérification post-commande&quot;">​</a></h2><p>La TUI charge toutes les specs de l&#39;espace de travail. Si une spec ne parvient pas à se charger, un message d&#39;erreur est affiché dans l&#39;interface.</p><h2 id="nuances" tabindex="-1">Nuances <a class="header-anchor" href="#nuances" aria-label="Permalink to &quot;Nuances&quot;">​</a></h2><ul><li><strong>Auto-initialisation :</strong> Si aucun fichier de configuration n&#39;existe, <code>run</code> exécute automatiquement l&#39;assistant d&#39;initialisation d&#39;abord.</li><li><strong>Pas de drapeaux :</strong> La commande <code>run</code> n&#39;a pas de drapeaux — toute la configuration provient de l&#39;espace de travail.</li><li><strong>Taille du terminal :</strong> La TUI nécessite un terminal d&#39;au moins 80×24 caractères. Elle peut ne pas s&#39;afficher correctement dans les très petits terminaux.</li><li><strong>Dépendances :</strong> La TUI utilise Bubbletea. Elle fonctionne via SSH et dans la plupart des émulateurs de terminal.</li></ul>',25)])])}const m=a(s,[["render",n]]);export{p as __pageData,m as default};
